import{_ as t,o as a,c as r,ag as e}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Epistemology/03-Descartes.md","filePath":"philosophy/Epistemology/03-Descartes.md"}'),i={name:"philosophy/Epistemology/03-Descartes.md"};function l(s,o,n,p,c,h){return a(),r("div",null,[...o[0]||(o[0]=[e('<h2 id="방법서설" tabindex="-1">방법서설 <a class="header-anchor" href="#방법서설" aria-label="Permalink to &quot;방법서설&quot;">​</a></h2><p>원제: 이성을 잘 인도하고, 학문에 있어 진리를 탐구하기 위한 방법서설.</p><p><strong>학문을 위한 방법 4가지</strong></p><ol><li><strong>명증성</strong>: 명석하고 판명하게 참이라고 인식한 것 외에는 어떤 것도 참으로 받아들이지 않음</li><li><strong>분석(분해)</strong>: 검토할 문제를 가능한 한 작은 부분으로 나눔</li><li><strong>종합(합성)</strong>: 가장 단순하고 알기 쉬운 것부터 차례로 복잡한 것에 대한 인식으로 올라감</li><li><strong>열거</strong>: 하나도 빠뜨리지 않았다고 확신할 수 있을 만큼 완벽하게 열거하고 전체적으로 검토함</li></ol><h2 id="고대-철학과의-차이점" tabindex="-1">고대 철학과의 차이점 <a class="header-anchor" href="#고대-철학과의-차이점" aria-label="Permalink to &quot;고대 철학과의 차이점&quot;">​</a></h2><p>물음의 초점이 대상이 아닌 <strong>주체</strong>로 향하게 됨. 외부세계나 대상이 아니라, 의심하고 사유하는 &#39;나&#39;의 존재를 철학의 제1원리로 삼음으로써 철학의 중심이 대상에서 주체로 옮겨감.</p><h2 id="코기토-cogito-논증" tabindex="-1">코기토(Cogito) 논증 <a class="header-anchor" href="#코기토-cogito-논증" aria-label="Permalink to &quot;코기토(Cogito) 논증&quot;">​</a></h2><p>모든 것을 의심(방법적 회의)해도 &#39;지금 의심하고 있다는 것&#39; 자체는 의심할 수 없음 — &quot;나는 생각한다, 고로 존재한다.&quot;</p><p><strong>확실성의 요소</strong></p><ol><li>1인칭 형식</li><li>현재형</li><li>사유작용/자기의식작용과 떨어져 있는 것에 대해서는 악신(사악한 정령)이 개입할 수 있음</li></ol><p><strong>코기토에 대한 비판</strong></p><ol><li>데카르트는 의식의 흐름을 인지하고 있을 뿐인데, 이를 통해 &#39;사유하는 나&#39;(실체)를 설명함 — 실체란 어떤 속성을 담지하는 궁극적 담지자이며, 속성을 가지되 다른 존재의 속성은 아닌 것. &#39;나&#39;는 사고라는 속성을 가지며 다른 존재의 속성이 아니라고 주장한 것인데, 이 추론이 정당한가?</li><li>이러한 추론의 형식 자체가 악신의 가설 문제에 걸리지 않는가? → 데카르트의 답: 이것은 추론이 아니라 <strong>직관</strong>이다 (전제로부터 결론을 이끌어내는 추론 과정이 아니라, 사유하는 동시에 직접적으로 파악되는 것이므로 악신의 개입 여지가 없음)</li></ol><h2 id="데카르트의-순환논증-cartesian-circle" tabindex="-1">데카르트의 순환논증 (Cartesian Circle) <a class="header-anchor" href="#데카르트의-순환논증-cartesian-circle" aria-label="Permalink to &quot;데카르트의 순환논증 (Cartesian Circle)&quot;">​</a></h2><ol><li>명석판명한 지각이 확실한 지식이기 위해서는 신이 존재해야 한다.</li><li>신이 존재한다는 것은 명석판명하게 지각된다.</li><li>따라서 신은 존재한다.</li><li>따라서 명석판명한 지각은 확실한 지식이다.</li></ol><p>→ 신의 존재를 명석판명한 지각으로 증명하면서, 그 명석판명한 지각의 신뢰성 자체를 신의 존재로 보증하려 하는 순환 구조라는 비판.</p><h2 id="아르키메데스적-기획" tabindex="-1">아르키메데스적 기획 <a class="header-anchor" href="#아르키메데스적-기획" aria-label="Permalink to &quot;아르키메데스적 기획&quot;">​</a></h2><p>아르키메데스가 &quot;지구를 움직이기 위해 단 하나의 확고부동한 점만&quot; 찾으려 했듯, 데카르트 역시 학문의 확고한 토대를 세우기 위해 **&quot;확실하고 흔들리지 않는 최소한의 것&quot;**을 발견하고자 함. 목적은 하나의 확실한 진리를 발견하고, 그것을 토대로 모든 학문의 체계를 재건축하는 것.</p><h2 id="표상주의와-이원론" tabindex="-1">표상주의와 이원론 <a class="header-anchor" href="#표상주의와-이원론" aria-label="Permalink to &quot;표상주의와 이원론&quot;">​</a></h2><p>**마음/의식(표상)**과 **외부세계(대상)**를 구분하는 구도 — 표상을 매개로 인식한다는 <strong>표상주의</strong>의 입장. (배와 선원의 비유: 영혼이 없으면 육체의 움직임이 불가능하다는 방식으로 플라톤의 이원론을 재서술)</p><p>세상에 존재하는 모든 것은 <strong>형상적 실재성</strong>을 지님.</p>',20)])])}const u=t(i,[["render",l]]);export{d as __pageData,u as default};
